package com.cryptostrategy.platform.leaderboard.api.model;import com.cryptostrategy.platform.evaluation.api.model.EvaluationResultId;import com.cryptostrategy.platform.experiment.api.ExperimentId;import java.math.BigDecimal;import java.util.Objects;public record LeaderboardEntry(LeaderboardRevisionId revisionId,ExperimentId experimentId,int rank,EvaluationResultId evaluationResultId,BigDecimal score,BigDecimal maximumDrawdown,String evaluationFingerprint){public LeaderboardEntry{Objects.requireNonNull(revisionId);Objects.requireNonNull(experimentId);Objects.requireNonNull(evaluationResultId);Objects.requireNonNull(score);Objects.requireNonNull(maximumDrawdown);Objects.requireNonNull(evaluationFingerprint);if(rank<1)throw new IllegalArgumentException("rank");}}
